import React, { ReactNode, useContext } from 'react';
import { isElement } from 'react-is';

import { SelectionChip } from './SelectionChip.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { DataTableContext } from '../contexts/DataTableContext.js';

// #region Typings
export interface DataTableSelectedRowsActionsProps {
  children: (rows: unknown[]) => ReactNode;
}

export type SelectedRowsActionsSlots = {
  selectionChip: ReactNode | null;
};
// #endregion Typings

/**
 * Selected rows actions component used for configuring actions
 * that can be applied on one or multiple rows in the DataTable simultaneously.
 * @param props - contains children.
 * @returns DataTableSelectedRowsActions containing children.
 */
export const DataTableSelectedRowsActions = (
  props: DataTableSelectedRowsActionsProps,
) => {
  const { currentSelectedRows } = useContext(DataTableContext);
  const { children } = props;
  const slots: SelectedRowsActionsSlots = {
    selectionChip: null,
  };

  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      switch (child.type) {
        case SelectionChip:
          slots.selectionChip = child;
          break;
      }
    }
  });

  if (typeof children !== 'function') {
    // eslint-disable-next-line no-console
    console.warn(
      'The SelectedRowActions sub-component child must be a function!',
    );
    return null;
  }

  return (
    <Flex
      justifyContent="flex-start"
      alignItems="flex-end"
      flex={1}
      flexWrap="wrap"
      paddingRight={4}
      paddingBottom={4}
      gap={4}
    >
      {children(currentSelectedRows)}
    </Flex>
  );
};

DataTableSelectedRowsActions['displayName'] = 'DataTable.SelectedRowsActions';
